{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-rkhytK/src/address.js","content":"/**
 * Cell address parsing and column-letter <-> index conversion.
 *
 * Columns run A..Z then AA..ZZ (index 1..702, bijective base-26).
 * Rows are 1..999 (one to three digits).
 */

const MAX_COL_LETTERS = 2
const MAX_ROW_DIGITS = 3

export function splitWord(word) {
  const m = /^([A-Za-z]+)([0-9]*)$/.exec(word)
  if (!m) return null
  return { letters: m[1], digits: m[2] }
}

export function colLettersToIndex(upperLetters) {
  let idx = 0
  for (const ch of upperLetters) {
    idx = idx * 26 + (ch.charCodeAt(0) - 64)
  }
  return idx
}

export function colIndexToLetters(idx) {
  if (idx <= 26) return String.fromCharCode(64 + idx)
  const rest = idx - 26
  const first = Math.floor((rest - 1) / 26) + 1
  const second = ((rest - 1) % 26) + 1
  return String.fromCharCode(64 + first) + String.fromCharCode(64 + second)
}

/**
 * Analyze an address-shaped word (letters + digits). Returns:
 *  - inRange: whether it is a real, addressable cell.
 *  - colIndex, row: only meaningful when inRange.
 *  - canonical: "COL"+row without leading zeros, only when inRange.
 */
export function analyzeAddressWord(letters, digits) {
  const upper = letters.toUpperCase()
  const shapeOk = upper.length >= 1 && upper.length <= MAX_COL_LETTERS &&
    digits.length >= 1 && digits.length <= MAX_ROW_DIGITS
  if (!shapeOk) return { inRange: false }
  const row = parseInt(digits, 10)
  if (row < 1) return { inRange: false }
  const colIndex = colLettersToIndex(upper)
  return { inRange: true, colIndex, row, canonical: upper + String(row) }
}

/** Strict parse of a full address string (used for the sheet's own declared addresses). */
export function parseStrictAddress(str) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(str)
  if (!m) return null
  const info = analyzeAddressWord(m[1], m[2])
  return info.inRange ? info : null
}

export function compareAddresses(a, b) {
  if (a.colIndex !== b.colIndex) return a.colIndex - b.colIndex
  return a.row - b.row
}
"}

