{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-rkhytK/src/tokenizer.js","content":"/**
 * Tokenizer for a formula body (the text after the leading `=`).
 */

const SIMPLE = {
  '(': 'LPAREN', ')': 'RPAREN', ',': 'COMMA', ':': 'COLON',
  '^': 'CARET', '*': 'STAR', '/': 'SLASH', '+': 'PLUS', '-': 'MINUS',
}

/** Returns { ok: true, tokens } or { ok: false } when a character is not part of the grammar. */
export function tokenize(text) {
  const tokens = []
  let i = 0
  const n = text.length
  while (i < n) {
    const ch = text[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    if (ch >= '0' && ch <= '9') {
      let j = i + 1
      while (j < n && text[j] >= '0' && text[j] <= '9') j++
      if (text[j] === '.') {
        let k = j + 1
        if (k < n && text[k] >= '0' && text[k] <= '9') {
          j = k
          while (j < n && text[j] >= '0' && text[j] <= '9') j++
        }
      }
      tokens.push({ type: 'NUM', value: parseFloat(text.slice(i, j)) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i + 1
      while (j < n && /[A-Za-z]/.test(text[j])) j++
      const letters = text.slice(i, j)
      let k = j
      while (k < n && text[k] >= '0' && text[k] <= '9') k++
      const digits = text.slice(j, k)
      tokens.push({ type: 'NAME', letters, digits })
      i = k
      continue
    }
    if (ch === '<') {
      if (text[i + 1] === '=') { tokens.push({ type: 'LE' }); i += 2; continue }
      if (text[i + 1] === '>') { tokens.push({ type: 'NE' }); i += 2; continue }
      tokens.push({ type: 'LT' }); i++; continue
    }
    if (ch === '>') {
      if (text[i + 1] === '=') { tokens.push({ type: 'GE' }); i += 2; continue }
      tokens.push({ type: 'GT' }); i++; continue
    }
    if (ch === '=') { tokens.push({ type: 'EQ' }); i++; continue }
    if (SIMPLE[ch]) { tokens.push({ type: SIMPLE[ch] }); i++; continue }
    return { ok: false }
  }
  tokens.push({ type: 'EOF' })
  return { ok: true, tokens }
}
"}

