 * Value representation: a number, text, a boolean, or an error token.
 */

export const NUM = (v) => ({ t: 'num', v })
export const TEXT = (v) => ({ t: 'text', v })
export const BOOL = (v) => ({ t: 'bool', v })
export const ERR = (v) => ({ t: 'err', v })

export const ERROR_TOKENS = new Set([
  '#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!',
])

/** Reads a value as a number for an arithmetic position: booleans are 1/0, text is #VALUE!. */
export function toNumber(value) {
  if (value.t === 'err') return value
  if (value.t === 'num') return value
  if (value.t === 'bool') return NUM(value.v ? 1 : 0)
  return ERR('#VALUE!')
}

/** Wraps a raw arithmetic result, turning a non-finite outcome into #DIV/0!. */
export function numResult(raw) {
  return Number.isFinite(raw) ? NUM(raw) : ERR('#DIV/0!')
}

export function divide(a, b) {
  if (b === 0) return ERR('#DIV/0!')
  return numResult(a / b)
}

function typeRank(v) {
  if (v.t === 'num') return 0
  if (v.t === 'text') return 1
  return 2 // bool
}

/** Compares two non-error values per the spec's cross-kind and same-kind rules. */
export function compareValues(a, b) {
  if (a.t !== b.t) return typeRank(a) - typeRank(b) < 0 ? -1 : 1
  if (a.t === 'num') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  if (a.t === 'text') return a.v < b.v ? -1 : a.v > b.v ? 1 : 0
  return (a.v ? 1 : 0) - (b.v ? 1 : 0)
}

/** Rounds to ten significant digits and formats as JavaScript would print the result. */
export function formatNumber(n) {
  if (n === 0) return '0'
  return String(Number(n.toPrecision(10)))
}

export function formatValue(value) {
  if (value.t === 'num') return formatNumber(value.v)
  if (value.t === 'text') return value.v
  if (value.t === 'bool') return value.v ? 'TRUE' : 'FALSE'
  return value.v
}
"}

