function splitLine(trimmed) {
  let i = 0
  while (i < trimmed.length && trimmed[i] !== ' ' && trimmed[i] !== '\t') i++
  const address = trimmed.slice(0, i)
  let rest = trimmed.slice(i)
  let j = 0
  while (j < rest.length && (rest[j] === ' ' || rest[j] === '\t')) j++
  const content = rest.slice(j)
  return { address, content }
}

/** Returns a Map of canonical address -> content string, in first-declared order. */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const raw = lines[idx]
    let start = 0
    while (start < raw.length && (raw[start] === ' ' || raw[start] === '\t')) start++
    const trimmed = raw.slice(start)
    if (trimmed === '' || trimmed[0] === '#') continue

    const { address, content } = splitLine(trimmed)
    const info = parseStrictAddress(address.toUpperCase())
    if (!info) throw new SheetError(lineNo, `invalid cell address ${address.toUpperCase()}`)
    const canonical = info.canonical
    if (cells.has(canonical)) throw new SheetError(lineNo, `cell ${canonical} is declared twice`)
    cells.set(canonical, content)
  }
  return cells
}
