 * Expands a range node's two corners into the cells it covers.
 */

import { colIndexToLetters } from './address.js'

/** True when both corners of a range node are addressable cells. */
export function rangeValid(node) {
  return node.from.inRange && node.to.inRange
}

/** Returns the covered cells' canonical addresses, ascending column then row. */
export function expandRange(node) {
  const c1 = node.from.colIndex, c2 = node.to.colIndex
  const r1 = node.from.row, r2 = node.to.row
  const colLo = Math.min(c1, c2), colHi = Math.max(c1, c2)
  const rowLo = Math.min(r1, r2), rowHi = Math.max(r1, r2)
  const cells = []
  for (let col = colLo; col <= colHi; col++) {
    const letters = colIndexToLetters(col)
    for (let row = rowLo; row <= rowHi; row++) {
      cells.push(letters + String(row))
    }
  }
  return cells
}
"}

