  if (val.t === 'err') return val
  const n = toNumber(val)
  if (n.t === 'err') return n
  return NUM(op === 'MINUS' ? -n.v : n.v)
}

const COMPARISON_OPS = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])

function evalComparison(op, left, right) {
  const cmp = compareValues(left, right)
  switch (op) {
    case 'EQ': return BOOL(cmp === 0)
    case 'NE': return BOOL(cmp !== 0)
    case 'LT': return BOOL(cmp < 0)
    case 'LE': return BOOL(cmp <= 0)
    case 'GT': return BOOL(cmp > 0)
    case 'GE': return BOOL(cmp >= 0)
  }
