  const ln = toNumber(left)
  if (ln.t === 'err') return ln
  const rn = toNumber(right)
  if (rn.t === 'err') return rn
  switch (op) {
    case 'PLUS': return numResult(ln.v + rn.v)
    case 'MINUS': return numResult(ln.v - rn.v)
    case 'STAR': return numResult(ln.v * rn.v)
    case 'SLASH': return divide(ln.v, rn.v)
    case 'CARET': return numResult(Math.pow(ln.v, rn.v))
  }
