{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e9-preset-craft-vs-plain-t5-20260919T125605Z/cell-rkhytK/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet, SheetError } from './sheet-parser.js'
import { parseFormula } from './formula-parser.js'
import { createCellReader } from './evaluate.js'
import { formulaDeps } from './deps.js'
import { formatValue } from './value.js'
import { sortCanonicalAddresses } from './address.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (c) => chunks.push(c))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exitCode = 2
}

async function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
    return
  }
  const mode = argv[0]
  const input = await readStdin()

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`line ${e.line}: ${e.message}`)
      return
    }
    throw e
  }

  const addresses = sortCanonicalAddresses(cells.keys())
  const lines = []

  if (mode === 'values') {
    const getValue = createCellReader(cells, parseFormula)
    for (const address of addresses) {
      lines.push(`${address}=${formatValue(getValue(address))}`)
    }
  } else {
    for (const address of addresses) {
      const content = cells.get(address)
      let deps = []
      if (content[0] === '=') {
        const ast = parseFormula(content.slice(1))
        if (ast) deps = formulaDeps(ast)
      }
      lines.push(`${address}:${deps.map((a) => ` ${a}`).join('')}`)
    }
  }

  const output = lines.length > 0 ? lines.join('\n') + '\n' : ''
  process.stdout.write(output)
}

main().catch((e) => {
  process.stderr.write(`error: ${e.message}\n`)
  process.exitCode = 2
})
"}

